import { z } from "zod";
import { LANGUAGE_IDS, LEVELS, LIMITS, MODES } from "@/lib/constants";

// The body of POST /api/runs. Sizes are checked here, before anything else
// runs, so an oversized paste is rejected without touching the database.

export const runRequestSchema = z
  .object({
    // Generated by the browser once per submission; the idempotency key.
    clientRequestId: z.uuid("Missing request id. Reload the page and try again."),
    mode: z.enum(MODES),
    language: z.enum(LANGUAGE_IDS),
    targetLanguage: z.enum(LANGUAGE_IDS).optional(),
    level: z.enum(LEVELS).optional(),
    framework: z
      .string()
      .trim()
      .max(40, "Keep the framework name under 40 characters.")
      .regex(/^[\w .+#/-]*$/, "Use letters, numbers and . + # - / only.")
      .optional()
      .transform((v) => v || undefined),
    input: z
      .string()
      .max(LIMITS.MAX_INPUT_CHARS, `Keep it under ${LIMITS.MAX_INPUT_CHARS.toLocaleString("en-US")} characters. Paste just the part you need help with.`)
      .refine((v) => v.trim().length > 0, "Paste some code (or, for Generate, describe what you want)."),
    extra: z
      .string()
      .max(LIMITS.MAX_EXTRA_CHARS, `Keep this under ${LIMITS.MAX_EXTRA_CHARS.toLocaleString("en-US")} characters.`)
      .optional()
      .transform((v) => (v?.trim() ? v : undefined)),
  })
  .superRefine((v, ctx) => {
    if (v.mode === "convert") {
      if (!v.targetLanguage) ctx.addIssue({ code: "custom", path: ["targetLanguage"], message: "Choose the language to convert to." });
      else if (v.targetLanguage === v.language) ctx.addIssue({ code: "custom", path: ["targetLanguage"], message: "Pick a different language from the source." });
    }
  })
  .transform((v) => ({
    ...v,
    // Fields that don't belong to the mode are dropped, matching the DB CHECKs.
    targetLanguage: v.mode === "convert" ? v.targetLanguage : undefined,
    level: v.mode === "explain" ? (v.level ?? "beginner") : undefined,
    framework: v.mode === "tests" ? v.framework : undefined,
    extra: v.mode === "fix" || v.mode === "generate" ? v.extra : undefined,
  }));

export type RunRequest = z.infer<typeof runRequestSchema>;
